/* MindConnect — rooms part 8: Genetics & inheritance (genes, decided, traits, passes, behaviour) */
(function(){
const {$,$$,esc,store,toast,openDrawer,W,reduce}=window.MC;
const R=window.ROOMS;
const GP={mm:"--stress",mf:"--glory",fm:"--violet",ff:"--living"};/* grandparent colours */
const GPN={mm:"mother's mother",mf:"mother's father",fm:"father's mother",ff:"father's father"};
const chromo=(x,y,h,top,bot,split)=>`<rect x="${x}" y="${y}" width="12" height="${h}" rx="6" fill="var(${top})"/>${split!=null?`<rect x="${x}" y="${y+h*split}" width="12" height="${h*(1-split)}" rx="${split>.8?6:3}" fill="var(${bot})"/>`:""}`;

/* ======================= GENETICS AT A GLANCE ======================= */
const CHANGE=[["DNA sequence",0],["Blood group",.05],["Eye colour",.12],["Adult height",.22],["Temperament",.4],["Disease risk",.5],["Gene expression",.6],["Weight & fitness",.68],["Stress reactivity",.75],["Emotional regulation",.85],["Attachment style",.9],["Habits & beliefs",1]];
R.genes={html:()=>`
${W.head("Genetics","Genetics at a glance","The whole story on one screen: how your DNA is decided, how traits pass on, what reaches a child, how genes relate to behaviour, what epigenetics does, and what can and can't change. Each panel opens a deeper room.")}
<section class="grid two">
 <a class="card click" href="#decided" style="text-decoration:none;color:inherit;border-top:3px solid var(--living)"><span class="mono" style="color:var(--living)">01 · How it's decided</span>
  <div class="diagram"><svg viewBox="0 0 320 120" style="min-width:0" aria-hidden="true">
   ${chromo(20,20,60,"--stress",null,null)}${chromo(36,20,60,"--glory",null,null)}${chromo(20,90,0,"--stress")}
   <g><animateTransform attributeName="transform" type="translate" values="0 0;0 0;0 0" dur="4s" repeatCount="indefinite"/>${chromo(70,20,60,"--violet",null,null)}${chromo(86,20,60,"--living",null,null)}</g>
   <path d="M110 50 L150 50" stroke="var(--muted)" stroke-width="2" class="flow-dash"/>
   <circle cx="200" cy="55" r="44" fill="var(--living-soft)" stroke="var(--living)"><animate attributeName="r" values="40;46;40" dur="3s" repeatCount="indefinite"/></circle>
   ${chromo(180,30,50,"--stress","--glory",.55)}${chromo(196,30,50,"--violet","--living",.35)}${chromo(212,30,50,"--glory","--stress",.7)}
   <text x="200" y="112" text-anchor="middle" font-size="10" fill="var(--muted)">a brand-new combination</text>
   <text x="275" y="45" font-size="10" fill="var(--fg)">23 + 23</text><text x="275" y="60" font-size="10" fill="var(--fg)">= 46</text>
  </svg></div>${W.list(["46 chromosomes in 23 pairs, one of each pair from each parent","Chromosomes shuffle and swap pieces before passing on","Every child is a new combination; siblings share about 50%"])}</a>
 <a class="card click" href="#traits" style="text-decoration:none;color:inherit;border-top:3px solid var(--glory)"><span class="mono" style="color:var(--glory)">02 · How traits pass on</span>
  <div class="diagram"><svg viewBox="0 0 320 120" style="min-width:0" aria-hidden="true">${Array.from({length:15},(_,i)=>{const h=90*Math.exp(-Math.pow((i-7)/3,2)/2);return`<rect x="${20+i*18}" y="${100-h}" width="15" height="${h}" fill="var(--living)" opacity=".45"><animate attributeName="height" values="0;${h}" dur="1s" begin="${i*.05}s" fill="freeze"/><animate attributeName="y" values="100;${100-h}" dur="1s" begin="${i*.05}s" fill="freeze"/></rect>`}).join("")}<path d="${Array.from({length:61},(_,i)=>{const x=20+i*4.5;const h=90*Math.exp(-Math.pow((x-20-7.5*18-27)/54,2)/2);return(i?"L":"M")+x+" "+(100-h)}).join(" ")}" fill="none" stroke="var(--fg)" stroke-dasharray="4 4"/><line x1="15" y1="100" x2="305" y2="100" stroke="var(--fg)"/><text x="20" y="114" font-size="9" fill="var(--muted)">shorter</text><text x="300" y="114" text-anchor="end" font-size="9" fill="var(--muted)">taller</text></svg></div>
  ${W.list(["Recessive (25%), dominant (50%), X-linked (mostly sons)","Most traits are polygenic: many small genes plus environment","Running in families ≠ only genes"])}</a>
 <a class="card click" href="#passes" style="text-decoration:none;color:inherit;border-top:3px solid var(--stress)"><span class="mono" style="color:var(--stress)">03 · What passes to a child</span>
  <div class="diagram"><svg viewBox="0 -6 320 126" style="min-width:0" aria-hidden="true">${[["DNA","--living"],["Womb","--stress"],["Marks","--violet"],["Home","--glory"],["World","--violet"]].map(([t,c],i)=>`<circle cx="${32+i*64}" cy="22" r="14" fill="var(${c})" fill-opacity=".2" stroke="var(${c})"/><text x="${32+i*64}" y="8" text-anchor="middle" font-size="9" fill="var(--fg)">${t}</text><path d="M${32+i*64} 36 C ${32+i*64} 80, 160 70, 160 92" fill="none" stroke="var(${c})" stroke-width="3" opacity=".7"/><circle r="3" fill="var(${c})"><animateMotion dur="${2+i*.3}s" repeatCount="indefinite" path="M${32+i*64} 36 C ${32+i*64} 80, 160 70, 160 92"/></circle>`).join("")}<circle cx="160" cy="100" r="16" fill="var(--living)"/><text x="160" y="104" text-anchor="middle" font-size="8" fill="var(--bg)">child</text></svg></div>
  ${W.list(["Five channels: DNA, womb, epigenetic marks, home, world","DNA gives tendencies, not memories, beliefs or skills","Many family patterns travel through relationships"])}</a>
 <a class="card click" href="#behaviour" style="text-decoration:none;color:inherit;border-top:3px solid var(--violet)"><span class="mono" style="color:var(--violet)">04 · Genes & behaviour</span>
  <div class="diagram"><svg viewBox="0 0 320 120" style="min-width:0" aria-hidden="true">${[["Height",80],["ADHD",74],["Intelligence (adult)",60],["Personality",40],["Depression",37],["Infant attachment",10]].map(([t,v],i)=>`<text x="108" y="${16+i*18}" text-anchor="end" font-size="9" fill="var(--fg)">${t}</text><rect x="114" y="${8+i*18}" width="0" height="10" rx="5" fill="var(--violet)" opacity=".6"><animate attributeName="width" values="0;${v*2}" dur="1.2s" begin="${i*.1}s" fill="freeze"/></rect>`).join("")}</svg></div>
  ${W.list(["Heritability describes differences in a group, not you","No single gene for anger, kindness or faith","Sensitive children suffer more in harsh settings and thrive more with support"])}</a>
 <div class="card" style="border-top:3px solid var(--violet)"><span class="mono" style="color:var(--violet)">05 · Epigenetics</span>
  <div class="diagram"><svg id="epiSvg" viewBox="0 0 320 120" style="min-width:0" role="img" aria-label="DNA packing open versus tight"></svg></div>
  <div class="seg" id="epiSeg"><button type="button" data-v="open" aria-pressed="true">Open: gene ON</button><button type="button" data-v="tight" aria-pressed="false">Tight + tags: gene OFF</button></div>
  ${W.list(["Chemical switches turn genes on or off","Stress, smoking, nutrition, care and exercise change them","Most marks reset between generations; human evidence for inherited marks is limited"])}<a href="#dna">Go deeper: DNA, the living script →</a></div>
 <div class="card" style="border-top:3px solid var(--stress)"><span class="mono" style="color:var(--stress)">06 · Can & can't change</span>
  <div style="display:flex;flex-direction:column;gap:10px"><div style="height:10px;border-radius:99px;background:linear-gradient(90deg,var(--stress),var(--glory),var(--living))"></div>
   <div class="grid" style="grid-template-columns:repeat(3,minmax(0,1fr));gap:8px" id="chgCols">${[["Fixed","--stress",0,.15],["Can influence","--glory",.15,.7],["Can change","--living",.7,1.01]].map(([t,c,lo,hi])=>`<div style="display:flex;flex-direction:column;gap:5px;min-width:0"><span class="mono" style="color:var(${c});font-size:.68rem">${t}</span>${CHANGE.filter(([,p])=>p>=lo&&p<hi).map(([n])=>`<span class="chip" style="border-color:var(${c});color:var(--fg);white-space:normal">${n}</span>`).join("")}</div>`).join("")}</div></div>
  ${W.list(["Fixed: DNA sequence, blood group, carrier status","Influence: disease risk, gene expression, stress reactivity","Change: habits, beliefs, regulation, attachment, what you pass on"])}</div>
</section>
${W.sec("Genetics through the relational gospel lens",null,`
<div class="grid">
 <div class="card"><span class="tag g">Known before formed</span><p>'Before I formed you in the womb I knew you' (Jer 1:5). 'You knitted me together in my mother's womb' (Ps 139:13). Genetics describes the knitting; it doesn't replace the Knitter.</p></div>
 <div class="card"><span class="tag l">Understanding replaces blame</span><p>'Who sinned, this man or his parents?' (John 9:2). Jesus refused the blame game. Knowing how traits pass on helps families respond with compassion.</p></div>
 <div class="card"><span class="tag v">Tendencies, not destinies</span><p>Genes load possibilities; love, choices and the Spirit shape which ones flourish. 'Choose life' (Deut 30:19).</p></div>
</div>`)}
`,mount(){
  const epi=v=>{$$("#epiSeg button").forEach(b=>b.setAttribute("aria-pressed",b.dataset.v===v));const open=v==="open";
   $("#epiSvg").innerHTML=`<rect x="0" y="0" width="320" height="120" rx="10" fill="var(${open?"--living-soft":"--stress-soft"})"/>`+
    (open?`<path d="M10 70 C 40 40, 60 100, 90 70 S 140 40, 170 70 S 220 100, 250 70 S 290 40, 310 70" fill="none" stroke="var(--violet)" stroke-width="3"/>${[50,130,210].map(x=>`<circle cx="${x}" cy="72" r="13" fill="var(--glory)" opacity=".6"/>`).join("")}<rect x="150" y="20" width="56" height="18" rx="9" fill="var(--living)"/><text x="178" y="33" text-anchor="middle" font-size="9" fill="var(--bg)">reader</text><circle r="4" fill="var(--living)"><animateMotion dur="3s" repeatCount="indefinite" path="M150 70 C 180 40, 220 100, 250 70"/></circle><text x="260" y="30" font-size="9" fill="var(--fg)">protein made</text><text x="160" y="110" text-anchor="middle" font-size="9" fill="var(--muted)">spools sit loosely, so the gene can be read</text>`
    :`${Array.from({length:7},(_,i)=>`<circle cx="${50+i*36}" cy="66" r="15" fill="var(--glory)" opacity=".6"/><circle cx="${58+i*36}" cy="54" r="4" fill="var(--violet)"><animate attributeName="r" values="0;4" dur=".4s" begin="${i*.1}s" fill="freeze"/></circle>`).join("")}<path d="M20 66 ${Array.from({length:7},(_,i)=>`q 18 -26 36 0`).join(" ")}" fill="none" stroke="var(--violet)" stroke-width="3"/><text x="300" y="40" text-anchor="end" font-size="18" fill="var(--stress)">✕</text><text x="160" y="110" text-anchor="middle" font-size="9" fill="var(--muted)">methyl tags (purple) and tight spools hide the gene</text>`)};
  $$("#epiSeg button").forEach(b=>b.addEventListener("click",()=>epi(b.dataset.v)));epi("open");
  
}};

/* ======================= HOW GENETICS IS DECIDED ======================= */
const ZOOM=[
 {k:"Body",s:"~37 trillion cells",d:"Each cell (except mature red blood cells) carries a full copy of your DNA."},
 {k:"Cell nucleus",s:"the control centre",d:"The nucleus stores your DNA, folded into a space about 6 micrometres across."},
 {k:"46 chromosomes",s:"23 pairs",d:"One of each pair came from your mother, one from your father. Think of them as 46 volumes of an instruction library."},
 {k:"DNA",s:"~3.1 billion letters per set",d:"Each chromosome is one very long DNA molecule written in four letters: A, T, C and G."},
 {k:"Genes → proteins",s:"~20,000 genes",d:"A gene is one recipe, usually for a protein. Proteins build and run the body."}
];
const NUMS=[["50 / 50","From each parent","Every child gets half of mum's DNA and half of dad's.","--living"],["8.4 million","Combinations per parent","2²³ ways to pick one chromosome from each pair, before any crossing over.","--glory"],["~70 trillion","Combinations per couple","8.4 million × 8.4 million. Crossing over makes it effectively endless.","--violet"],["~25%","From each grandparent","On average. It varies, so one grandparent may contribute more.","--stress"],["38-62%","Shared by siblings","Average 50%. Identical twins share ~100% (they come from one fertilised egg).","--violet"],["~60-70","New mutations per child","Fresh changes not in either parent; about 2 more for each extra year of the father's age. Most are harmless.","--stress"]];
const GLOSS=[["DNA","The instruction book, written in 4 letters: A, T, C, G"],["Gene","One recipe in the book, usually for a protein"],["Chromosome","A tightly packed volume of the book (46 volumes)"],["Allele","A version of a gene, e.g. for blood group A or B"],["Genotype","The versions you carry"],["Phenotype","What actually shows: your traits, shaped by genes and environment"],["Mutation / variant","A spelling difference in DNA. Most are harmless; a few cause disease"],["99.9%","How much DNA any two people share. All human variety lives in the other 0.1%"]];
R.decided={html:()=>`
${W.head("Genetics","How your genetics is decided","Your DNA is decided in one moment, at conception, by a shuffle of your parents' chromosomes. Zoom in, watch the shuffle, then run the lottery yourself.")}
${W.sec("Zoom in: from body to protein","Auto-plays; tap any step.",`
<div class="panel"><div class="diagram"><svg id="zoomSvg" viewBox="0 0 760 170" role="img" aria-label="Zoom from body to genes">
 ${ZOOM.map((z,i)=>`<g class="zm" data-i="${i}" style="cursor:pointer"><circle cx="${80+i*150}" cy="70" r="52" fill="var(--bg)" stroke="var(--line)" stroke-width="2"/>${i<4?`<path d="M${134+i*150} 70 L${176+i*150} 70" stroke="var(--living)" stroke-width="2" stroke-dasharray="3 5"/><polygon points="${176+i*150},64 ${186+i*150},70 ${176+i*150},76" fill="var(--living)"/>`:""}<text x="${80+i*150}" y="144" text-anchor="middle" font-size="12" font-weight="700" fill="var(--fg)">${z.k}</text><text x="${80+i*150}" y="160" text-anchor="middle" font-size="9.5" fill="var(--muted)">${z.s}</text></g>`).join("")}
 <g pointer-events="none"><circle cx="80" cy="50" r="10" fill="var(--living)"/><path d="M80 60 L80 92 M66 72 L94 72 M80 92 L68 112 M80 92 L92 112" stroke="var(--living)" stroke-width="7" stroke-linecap="round"/>
 <ellipse cx="230" cy="70" rx="38" ry="28" fill="var(--glory-soft)"/><circle cx="234" cy="68" r="15" fill="var(--glory)" opacity=".8"/>
 <text x="380" y="62" text-anchor="middle" font-size="28" font-weight="800" fill="var(--stress)">X</text><text x="364" y="92" text-anchor="middle" font-size="24" font-weight="800" fill="var(--violet)">X</text><text x="398" y="94" text-anchor="middle" font-size="22" font-weight="800" fill="var(--stress)">X</text>
 <path d="M515 28 C 545 50, 515 70, 545 92 S 515 112, 530 118 M545 28 C 515 50, 545 70, 515 92 S 545 112, 530 118" stroke="var(--violet)" stroke-width="3" fill="none"><animateTransform attributeName="transform" type="translate" values="0 0;0 -4;0 0" dur="3s" repeatCount="indefinite"/></path>
 <rect x="640" y="40" width="80" height="10" rx="5" fill="var(--bg3)"/><rect x="668" y="40" width="22" height="10" fill="var(--glory)"/><path d="M680 54 L680 74" stroke="var(--living)" stroke-width="2"/><ellipse cx="682" cy="92" rx="18" ry="10" fill="var(--violet)" opacity=".7"/></g>
 <circle id="zMark" cx="80" cy="70" r="56" fill="none" stroke="var(--glory)" stroke-width="3" style="transition:cx .6s"/>
</svg></div><div id="zOut" class="card" style="background:var(--bg);margin-top:8px"></div></div>`)}
${W.sec("From two parents to one new person","Press play: shuffle, split, combine. Colours show which grandparent each piece came from.",`
<div class="panel"><div class="row" style="justify-content:space-between"><div class="row" style="gap:12px;font-size:.8rem;color:var(--muted)">${Object.entries(GPN).map(([k,n])=>`<span><b style="color:var(${GP[k]})">■</b> from ${n}</span>`).join("")}</div><button class="btn primary" type="button" id="shufPlay">Play the shuffle</button></div>
<div class="diagram" style="margin-top:10px"><svg id="shufSvg" viewBox="0 0 760 300" role="img" aria-label="Chromosome shuffle"></svg></div>
<div class="grid" style="margin-top:6px">${[["1 · Shuffle","Inside the parent's body each chromosome pair lines up and swaps pieces (crossing over). Every egg and sperm ends up with a different mix."],["2 · Split","The pairs separate, so each egg or sperm carries just one of each pair: 23 single chromosomes. Which one goes in is random, like 23 coin tosses."],["3 · Combine","At fertilisation, 23 from the egg join 23 from the sperm. The child gets exactly half of each parent's DNA, but a different half from any sibling."]].map(([t,d],i)=>`<div class="card stp" data-i="${i}" style="background:var(--bg)"><h4 style="color:var(--living)">${t}</h4><p>${d}</p></div>`).join("")}</div></div>`)}
${W.sec("Run the genetic lottery","Conceive two siblings and see how much DNA each got from each grandparent, and how much they share.",`
<div class="split"><div class="panel" style="display:flex;flex-direction:column;gap:12px">
 <div class="row"><button class="btn primary" type="button" id="lotA">Conceive child A</button><button class="btn" type="button" id="lotB">Conceive child B</button></div>
 <div id="lotOut" style="display:flex;flex-direction:column;gap:12px"></div></div>
<div class="panel" style="display:flex;flex-direction:column;gap:10px"><span class="mono muted">Siblings compared</span><div style="font-family:var(--f-display);font-size:3rem;line-height:1" id="sibPct">—</div><span class="muted" id="sibTxt">Conceive both children to compare.</span><p class="muted" style="font-size:.85rem">Simulated across all 23 chromosome pairs with random crossing over. Real siblings share 38–62%, averaging 50%.</p></div></div>`)}
${W.sec("The numbers behind the lottery",null,`<div class="grid">${NUMS.map(([n,t,d,c])=>`<div class="card" style="border-top:3px solid var(${c})"><span style="font-family:var(--f-display);font-size:1.9rem;color:var(${c});line-height:1.1">${n}</span><h4>${t}</h4><p>${d}</p></div>`).join("")}</div>`)}
${W.sec("How biological sex is set","Tap the sperm.",`
<div class="split"><div class="panel"><div class="diagram"><svg id="sexSvg" viewBox="0 0 420 200" style="min-width:0" role="img" aria-label="Sex determination"><text x="70" y="24" text-anchor="middle" font-size="11" fill="var(--muted)">Mother's eggs</text><rect x="40" y="34" width="60" height="40" rx="10" fill="var(--stress-soft)" stroke="var(--stress)"/><text x="70" y="61" text-anchor="middle" font-size="18" font-weight="700" fill="var(--fg)">X</text><text x="70" y="92" text-anchor="middle" font-size="10" fill="var(--muted)">always X</text>
 <text x="70" y="120" text-anchor="middle" font-size="11" fill="var(--muted)">Father's sperm</text>${["X","Y"].map((s,i)=>`<g class="sp" data-s="${s}" style="cursor:pointer"><rect x="${22+i*62}" y="130" width="52" height="40" rx="10" fill="var(--violet-soft)" stroke="var(--violet)"/><text x="${48+i*62}" y="157" text-anchor="middle" font-size="18" font-weight="700" fill="var(--fg)">${s}</text></g>`).join("")}<text x="70" y="190" text-anchor="middle" font-size="10" fill="var(--muted)">X or Y (50/50)</text>
 <rect x="200" y="70" width="190" height="70" rx="16" fill="var(--bg)" stroke="var(--line)" id="sexRes"/><text x="295" y="100" text-anchor="middle" font-size="18" font-weight="700" fill="var(--fg)" id="sexT">? + ?</text><text x="295" y="122" text-anchor="middle" font-size="10" fill="var(--muted)" id="sexS">tap X or Y</text></svg></div></div>
<div class="panel" style="display:flex;flex-direction:column;gap:10px"><span class="tag v">Only from mother: mitochondrial DNA</span><p>Tiny power stations in every cell (mitochondria) carry their own 37 genes. They come almost only from the mother's egg, so they pass unchanged down the maternal line. Scientists use this to trace ancestry. The Y chromosome likewise passes almost unchanged from father to son.</p>
<div class="diagram"><svg viewBox="0 0 300 120" style="min-width:0" aria-label="Maternal line">${[[150,16,1],[90,60,1],[210,60,0],[60,104,1],[120,104,0],[180,104,0],[240,104,0]].map(([x,y,m])=>`<circle cx="${x}" cy="${y}" r="12" fill="${m?"var(--glory)":"var(--bg3)"}" stroke="var(--glory)"/>`).join("")}<path d="M150 28 L90 48 M150 28 L210 48 M90 72 L60 92 M90 72 L120 92 M210 72 L180 92 M210 72 L240 92" stroke="var(--line)" stroke-width="2"/><path d="M150 28 L90 48 M90 72 L60 92" stroke="var(--glory)" stroke-width="3" class="flow-dash"/></svg></div>
<p class="muted" style="font-size:.82rem">A small number of people have other patterns (such as XXY, or X only) or differences in sex development.</p></div></div>`)}
${W.sec("Genes in plain words","Tap a card to flip it.",`<div class="grid">${GLOSS.map(([t,d])=>`<button type="button" class="tile gl" data-d="${esc(d)}" data-t="${esc(t)}" style="min-height:90px;justify-content:center"><b style="font-size:1.1rem">${t}</b><span>tap to reveal</span></button>`).join("")}</div>`)}
${W.sec("Relational lens",null,`<div class="card" style="background:var(--violet-soft);border-color:transparent"><p style="color:var(--fg)">Every child is genuinely new, never a copy of either parent. That is good news: a child is a person to discover, not a repeat of the family story. 'I praise you, for I am fearfully and wonderfully made' (Ps 139:14). God's creativity shows in roughly 70 trillion possible combinations from one couple.</p></div>`)}
`,mount(){
  let zi=0,zt;const zs=i=>{zi=i%ZOOM.length;const z=ZOOM[zi];$("#zMark").setAttribute("cx",80+zi*150);$("#zOut").innerHTML=`<span class="tag l">${z.s}</span><h4 style="margin-top:6px">${z.k}</h4><p style="color:var(--fg)">${z.d}</p>`};
  $$("#zoomSvg .zm").forEach(g=>g.addEventListener("click",()=>{clearInterval(zt);zs(+g.dataset.i)}));zs(0);if(!reduce)zt=setInterval(()=>{if(!$("#zMark")){clearInterval(zt);return}zs(zi+1)},3500);
  /* shuffle animation */
  const sv=$("#shufSvg");
  const draw=st=>{const row=(y,a,b,lab,box)=>{let s=`<rect x="10" y="${y-10}" width="170" height="120" rx="12" fill="var(${box})" opacity=".35"/><text x="20" y="${y+4}" font-size="11" font-weight="700" fill="var(--fg)">${lab}: 23 pairs (3 shown)</text>`;
     [0,1,2].forEach(k=>{const x=30+k*50,h=[80,64,48][k];s+=chromo(x,y+20,h,a,null,null)+chromo(x+16,y+20,h,b,null,null)});
     s+=`<path d="M185 ${y+50} L210 ${y+50}" stroke="var(--living)" stroke-width="2"/><rect x="215" y="${y-10}" width="160" height="120" rx="12" fill="var(--bg3)" opacity="${st>=1?1:.3}"/><text x="295" y="${y+4}" text-anchor="middle" font-size="11" font-weight="700" fill="var(--fg)">Pairs swap pieces</text>`;
     if(st>=1)[0,1,2].forEach(k=>{const x=235+k*50,h=[80,64,48][k],sp=[.55,.4,.65][k];s+=chromo(x,y+20,h,a,b,sp)+chromo(x+16,y+20,h,b,a,sp)+`<text x="${x+14}" y="${y+22+h*sp}" font-size="11" fill="var(--fg)">×</text>`});
     s+=`<path d="M380 ${y+50} L405 ${y+50}" stroke="var(--living)" stroke-width="2"/>`;
     if(st>=2){s+=`<circle cx="455" cy="${y+50}" r="48" fill="var(${box})" fill-opacity=".35" stroke="var(${a})"/><text x="455" y="${y-4}" text-anchor="middle" font-size="10.5" font-weight="700" fill="var(--fg)">${lab==="Mother"?"Egg":"Sperm"}: 23 single</text>`;[0,1,2].forEach(k=>{const h=[56,44,34][k],sp=[.55,.4,.65][k];const pick=k%2;s+=chromo(430+k*20,y+30,h,pick?b:a,pick?a:b,sp)})}
     return s};
   let s=row(30,"--stress","--glory","Mother","--stress-soft")+row(170,"--violet","--living","Father","--violet-soft");
   if(st>=3){s+=`<path d="M503 80 C 560 90, 580 130, 600 140 M503 220 C 560 210, 580 170, 600 160" fill="none" stroke="var(--living)" stroke-width="2.5" class="flow-dash"/><circle cx="670" cy="150" r="80" fill="var(--living-soft)" stroke="var(--living)" stroke-width="2"><animate attributeName="r" values="76;82;76" dur="3s" repeatCount="indefinite"/></circle><text x="670" y="60" text-anchor="middle" font-size="11" font-weight="700" fill="var(--fg)">Fertilised egg: 46</text>`;
    [[0,"--stress","--glory",.55],[1,"--glory","--stress",.4],[2,"--stress","--glory",.65]].forEach(([k,a,b,sp])=>{s+=chromo(620+k*34,110,[56,44,34][k],a,b,sp)+chromo(636+k*34,110,[56,44,34][k],k===1?"--living":"--violet",k===1?"--violet":"--living",sp)});s+=`<text x="670" y="250" text-anchor="middle" font-size="11" fill="var(--living)">a brand-new combination</text>`}
   sv.innerHTML=s;$$(".stp").forEach((c,i)=>c.style.borderColor=st-1===i||(st===3&&i===2)?"var(--living)":"var(--line)")};
  draw(3);let busy=false;$("#shufPlay").onclick=()=>{if(busy)return;busy=true;let st=0;draw(0);const t=setInterval(()=>{st++;if(!$("#shufSvg")){clearInterval(t);return}draw(st);if(st>=3){clearInterval(t);busy=false}},reduce?10:1100)};
  /* lottery */
  const child=()=>{const pairs=[];const tot={mm:0,mf:0,fm:0,ff:0};for(let c=0;c<23;c++){const mx=Math.random(),fx=Math.random();const mFirst=Math.random()<.5,fFirst=Math.random()<.5;pairs.push({mx,fx,mFirst,fFirst});tot[mFirst?"mm":"mf"]+=mx;tot[mFirst?"mf":"mm"]+=1-mx;tot[fFirst?"fm":"ff"]+=fx;tot[fFirst?"ff":"fm"]+=1-fx}Object.keys(tot).forEach(k=>tot[k]=tot[k]/46*100);return{pairs,tot}};
  let kids={};const show=(k)=>{const c=kids[k];$("#lotOut").innerHTML=Object.keys(kids).map(n=>{const c=kids[n];return`<div class="card" style="background:var(--bg)"><b>Child ${n}</b><div class="diagram"><svg viewBox="0 0 470 70" style="min-width:0" aria-label="Chromosomes of child ${n}">${c.pairs.map((p,i)=>{const x=6+i*20,h=56;const ma=p.mFirst?"--stress":"--glory",mb=p.mFirst?"--glory":"--stress",fa=p.fFirst?"--violet":"--living",fb=p.fFirst?"--living":"--violet";return`<rect x="${x}" y="6" width="7" height="${h}" rx="3.5" fill="var(${ma})"/><rect x="${x}" y="${6+h*p.mx}" width="7" height="${h*(1-p.mx)}" rx="2" fill="var(${mb})"/><rect x="${x+8}" y="6" width="7" height="${h}" rx="3.5" fill="var(${fa})"/><rect x="${x+8}" y="${6+h*p.fx}" width="7" height="${h*(1-p.fx)}" rx="2" fill="var(${fb})"/>`}).join("")}</svg></div>
   <div class="meters">${Object.keys(GPN).map(g=>`<div class="meter" style="grid-template-columns:130px 1fr 44px"><span style="font-size:.8rem">${GPN[g]}</span><div class="bar"><i style="width:${c.tot[g]*2}%;background:var(${GP[g]})"></i></div><span class="v">${c.tot[g].toFixed(1)}%</span></div>`).join("")}</div></div>`}).join("");
   if(kids.A&&kids.B){let sh=0;for(let i=0;i<23;i++){const a=kids.A.pairs[i],b=kids.B.pairs[i];const seg=(x1,f1,x2,f2)=>{/* overlap of same-grandparent segments on [0,1] */const A1=f1?[0,x1]:[x1,1],B1=f2?[0,x2]:[x2,1];const ov=(p,q)=>Math.max(0,Math.min(p[1],q[1])-Math.max(p[0],q[0]));const A2=f1?[x1,1]:[0,x1],B2=f2?[x2,1]:[0,x2];return ov(A1,B1)+ov(A2,B2)};sh+=seg(a.mx,a.mFirst,b.mx,b.mFirst)+seg(a.fx,a.fFirst,b.fx,b.fFirst)}const pct=sh/46*100;$("#sibPct").textContent=pct.toFixed(0)+"%";$("#sibTxt").textContent="of their parent-inherited DNA came from the same grandparent segments. Try again: it changes every time."}};
  $("#lotA").onclick=()=>{kids.A=child();show("A")};$("#lotB").onclick=()=>{kids.B=child();show("B")};kids.A=child();show("A");
  $$("#sexSvg .sp").forEach(g=>g.addEventListener("click",()=>{const s=g.dataset.s;$("#sexT").textContent=`X + ${s} = X${s}`;$("#sexS").textContent=s==="X"?"usually develops as female":"SRY gene on Y starts male development";$("#sexRes").setAttribute("fill",s==="X"?"var(--stress-soft)":"var(--violet-soft)")}));
  $$(".gl").forEach(b=>b.addEventListener("click",()=>{const f=b.dataset.f==="1";b.dataset.f=f?"0":"1";b.innerHTML=f?`<b style="font-size:1.1rem">${b.dataset.t}</b><span>tap to reveal</span>`:`<span class="mono" style="color:var(--glory)">${b.dataset.t}</span><b style="font-weight:500">${b.dataset.d}</b>`}));
}};

/* ======================= HOW TRAITS PASS ON ======================= */
const PUN={
 rec:{t:"Recessive: both parents carriers",top:["A","a"],side:["A","a"],tl:"Parent 1: carrier (Aa)",sl:"Parent 2: carrier (Aa)",cells:[["AA","not affected",0],["Aa","carrier",1],["Aa","carrier",1],["aa","affected",2]],sum:"Each pregnancy: 25% affected, 50% carriers, 25% not carriers. A condition can 'skip' generations because carriers usually have no symptoms.",ex:"Thalassaemia, sickle cell disease, cystic fibrosis. In India about 3–4% of people carry beta-thalassaemia, so carrier testing before pregnancy is widely recommended."},
 dom:{t:"Dominant: one copy is enough",top:["A","a"],side:["a","a"],tl:"Affected parent (Aa)",sl:"Unaffected parent (aa)",cells:[["Aa","affected",2],["aa","not affected",0],["Aa","affected",2],["aa","not affected",0]],sum:"Each pregnancy: 50% chance. It does not skip generations.",ex:"Huntington's disease, Marfan syndrome, familial high cholesterol."},
 x:{t:"X-linked: mostly affects sons",top:["Xᶜ","X"],side:["X","Y"],tl:"Carrier mother (XᶜX)",sl:"Father (XY)",cells:[["XᶜX","carrier daughter",1],["XX","daughter",0],["XᶜY","affected son",2],["XY","son",0]],sum:"Sons have only one X, so one faulty copy shows. Daughters usually have a backup X.",ex:"Red-green colour blindness (about 1 in 12 men of European descent, fewer women), haemophilia, Duchenne muscular dystrophy."}
};
const BG={A:["AA","AO"],B:["BB","BO"],AB:["AB"],O:["OO"]};
R.traits={html:()=>`
${W.head("Genetics","How traits are passed on","Five inheritance patterns explain almost everything you see in families, from blood groups to rare conditions to height. Try the squares, simulate a family, and shift the height curve.")}
${W.sec("Single-gene patterns: the Punnett square","Choose a pattern, then simulate 100 children.",`
<div class="panel"><div class="seg" id="punSeg">${Object.entries(PUN).map(([k,p],i)=>`<button type="button" data-v="${k}" aria-pressed="${i===0}">${["Recessive","Dominant","X-linked"][i]}</button>`).join("")}</div>
<div class="split" style="margin-top:14px"><div class="diagram"><svg id="punSvg" viewBox="0 0 340 300" style="min-width:0;max-width:380px" role="img" aria-label="Punnett square"></svg></div>
<div style="display:flex;flex-direction:column;gap:10px"><h3 id="punT"></h3><p id="punS"></p><p class="muted" id="punE" style="font-size:.88rem"></p><button class="btn primary" type="button" id="punSim">Simulate 100 children</button><div class="diagram"><svg id="punDots" viewBox="0 0 300 120" style="min-width:0" aria-label="100 simulated children"></svg></div><div id="punCount" class="row" style="gap:12px;font-size:.85rem"></div></div></div></div>`)}
${W.sec("Polygenic: how most traits work","Height, skin colour, build, intelligence, personality and most mental-health risks come from hundreds or thousands of genes, each a tiny nudge, plus environment. Move the sliders.",`
<div class="split"><div class="panel"><div class="diagram"><svg id="polySvg" viewBox="0 0 440 220" style="min-width:0" role="img" aria-label="Distribution of height"></svg></div></div>
<div class="panel" style="display:flex;flex-direction:column;gap:12px">
 <label class="lbl" for="polyN"><span>Number of genes involved</span><span class="mono" id="polyNv">12</span></label><input id="polyN" type="range" min="1" max="40" value="12">
 <label class="lbl" for="polyE"><span>Nutrition & environment</span><span class="mono" id="polyEv">average</span></label><input id="polyE" type="range" min="-30" max="30" value="0">
 <p id="polyTxt" style="font-size:.93rem"></p>
 <p class="muted" style="font-size:.85rem">Real example: height is about 80% heritable, yet South Korean women gained about 20 cm in average height during the 20th century as nutrition improved (NCD-RisC, 2016).</p></div></div>`)}
${W.sec("Co-dominant: blood groups","A and B both show; O is recessive. Pick two parents.",`
<div class="split"><div class="panel" style="display:flex;flex-direction:column;gap:12px">
 <div class="row"><span style="width:80px">Parent 1</span><div class="seg" id="bg1">${Object.keys(BG).map((k,i)=>`<button type="button" data-v="${k}" aria-pressed="${k==="A"}">${k}</button>`).join("")}</div></div>
 <div class="row"><span style="width:80px">Parent 2</span><div class="seg" id="bg2">${Object.keys(BG).map((k,i)=>`<button type="button" data-v="${k}" aria-pressed="${k==="B"}">${k}</button>`).join("")}</div></div>
 <p class="muted" style="font-size:.85rem">The Rh factor (+ / −) is inherited separately: + is dominant.</p></div>
<div class="panel" style="display:flex;flex-direction:column;gap:10px"><span class="mono muted">Possible children</span><div class="row" id="bgOut" style="gap:10px"></div><p id="bgTxt" class="muted" style="font-size:.88rem"></p></div></div>`)}
${W.sec("Common myths, corrected","Tap a myth.",`<div class="grid">${[["Eye colour is one gene","At least 10+ genes are involved. Two blue-eyed parents can, rarely, have a brown-eyed child."],["It runs in the family, so it's genetic","Families share homes, food, habits and stress too. Running in families ≠ only genes."],["I have the gene for it","For most conditions a single variant only nudges risk slightly. Very few genes act like on/off switches."],["Children get more from one parent","DNA is 50/50 (plus a little extra mitochondrial DNA from mum). Looks may favour one side by chance."]].map(([m,t])=>`<button type="button" class="tile myth" data-t="${esc(t)}" data-m="${esc(m)}" style="min-height:120px"><span class="tag s">Myth</span><b>"${m}"</b><span>tap for the truth</span></button>`).join("")}</div>`)}
${W.sec("Relational lens",null,`<div class="card" style="background:var(--violet-soft);border-color:transparent"><p style="color:var(--fg)">Knowing how a condition is inherited replaces blame with understanding. 'Who sinned, this man or his parents?' Jesus answered: neither (John 9:2-3). No one chooses the genes they pass on; genetic counselling helps families decide together with accurate information. And 'the son shall not bear the iniquity of the father' (Ezek 18:20): genes are not guilt.</p></div>`)}
`,mount(){
  let mode="rec";const col=[ "--living","--glory","--stress"];
  const pun=v=>{mode=v;const p=PUN[v];$$("#punSeg button").forEach(b=>b.setAttribute("aria-pressed",b.dataset.v===v));
   $("#punSvg").innerHTML=`<text x="210" y="22" text-anchor="middle" font-size="11" font-weight="700" fill="var(--fg)">${p.tl}</text>${p.top.map((a,i)=>`<rect x="${130+i*100}" y="34" width="60" height="34" rx="8" fill="var(${a.includes("a")||a.includes("ᶜ")?"--stress-soft":"--living-soft"})"/><text x="${160+i*100}" y="57" text-anchor="middle" font-size="15" font-weight="700" fill="var(--fg)">${a}</text>`).join("")}
    <text x="18" y="190" transform="rotate(-90 18 190)" text-anchor="middle" font-size="11" font-weight="700" fill="var(--fg)">${p.sl}</text>${p.side.map((a,i)=>`<rect x="40" y="${100+i*100}" width="50" height="34" rx="8" fill="var(${a==="a"&&v==="rec"?"--stress-soft":"--living-soft"})"/><text x="65" y="${123+i*100}" text-anchor="middle" font-size="15" font-weight="700" fill="var(--fg)">${a}</text>`).join("")}
    ${p.cells.map(([g,l,s],i)=>{const x=110+(i%2)*100,y=80+Math.floor(i/2)*100;return`<rect x="${x}" y="${y}" width="90" height="90" rx="12" fill="var(${col[s]})" fill-opacity="${s===2?.85:.25}"><animate attributeName="opacity" values="0;1" dur=".5s" begin="${i*.15}s" fill="freeze"/></rect><text x="${x+45}" y="${y+44}" text-anchor="middle" font-size="18" font-weight="700" fill="${s===2?"var(--bg)":"var(--fg)"}">${g}</text><text x="${x+45}" y="${y+64}" text-anchor="middle" font-size="10" fill="${s===2?"var(--bg)":"var(--muted)"}">${l}</text>`}).join("")}`;
   $("#punT").textContent=p.t;$("#punS").textContent=p.sum;$("#punE").textContent="Examples: "+p.ex;$("#punDots").innerHTML="";$("#punCount").innerHTML=""};
  $$("#punSeg button").forEach(b=>b.addEventListener("click",()=>pun(b.dataset.v)));pun("rec");
  $("#punSim").onclick=()=>{const p=PUN[mode];const kids=Array.from({length:100},()=>p.cells[Math.floor(Math.random()*4)]);const cnt={};
   $("#punDots").innerHTML=kids.map((k,i)=>{cnt[k[1]]=(cnt[k[1]]||0)+1;return`<circle cx="${10+(i%20)*14.5}" cy="${14+Math.floor(i/20)*22}" r="6" fill="var(${col[k[2]]})" opacity="0"><animate attributeName="opacity" values="0;1" dur=".2s" begin="${i*.015}s" fill="freeze"/></circle>`}).join("");
   $("#punCount").innerHTML=Object.entries(cnt).map(([l,n])=>`<span class="chip">${l}: ${n}</span>`).join("")+`<span class="muted" style="font-size:.8rem">Chance varies run to run; each pregnancy is a new coin toss.</span>`};
  const poly=()=>{const n=+$("#polyN").value,e=+$("#polyE").value;$("#polyNv").textContent=n;$("#polyEv").textContent=e>8?"better":e<-8?"poorer":"average";
   const bins=n+1;const W0=380,H0=160;const p=[];for(let k=0;k<=n;k++){let c=1;for(let j=0;j<k;j++)c=c*(n-j)/(j+1);p.push(c/Math.pow(2,n))}const mx=Math.max(...p);const bw=W0/bins;
   $("#polySvg").innerHTML=`<line x1="30" y1="180" x2="420" y2="180" stroke="var(--fg)"/>`+p.map((v,k)=>`<rect x="${30+k*bw+1+e}" y="${180-v/mx*H0}" width="${Math.max(1,bw-2)}" height="${v/mx*H0}" fill="var(--living)" opacity=".55" style="transition:all .4s"/>`).join("")+`<text x="30" y="200" font-size="11" fill="var(--muted)">shorter</text><text x="420" y="200" text-anchor="end" font-size="11" fill="var(--muted)">taller</text>${e?`<text x="${225+e}" y="14" text-anchor="middle" font-size="10" fill="var(--glory)">${e>0?"→ same genes, better nutrition":"← same genes, poorer nutrition"}</text>`:""}`;
   $("#polyTxt").innerHTML=n<3?"With one or two genes you get a few neat categories, like pea colour in Mendel's garden.":n<15?"Add more genes and the categories blur into a smooth range.":"With many genes you get the familiar bell curve: most people near the middle, a few at each end. That's how height, intelligence and temperament work."};
  $("#polyN").oninput=poly;$("#polyE").oninput=poly;poly();
  const bg=()=>{const a=$("#bg1 [aria-pressed=true]").dataset.v,b=$("#bg2 [aria-pressed=true]").dataset.v;const out=new Set();BG[a].forEach(g1=>BG[b].forEach(g2=>{for(const x of g1)for(const y of g2){const s=[x,y].sort().join("");out.add(s==="AA"||s==="AO"?"A":s==="BB"||s==="BO"?"B":s==="AB"?"AB":"O")}}));
   const all=["A","B","AB","O"];$("#bgOut").innerHTML=all.map(t=>`<span style="width:58px;height:58px;border-radius:50%;display:grid;place-items:center;font-weight:700;font-size:1.1rem;background:${out.has(t)?"var(--stress)":"var(--bg3)"};color:${out.has(t)?"var(--bg)":"var(--muted)"};transition:all .3s">${t}</span>`).join("");
   $("#bgTxt").textContent=`${a} + ${b}: child can be ${[...out].join(", ")}${all.filter(t=>!out.has(t)).length?`, never ${all.filter(t=>!out.has(t)).join(" or ")}`:""}. (Assumes either genotype is possible for A or B parents.)`};
  ["bg1","bg2"].forEach(id=>$$(`#${id} button`).forEach(b=>b.addEventListener("click",()=>{$$(`#${id} button`).forEach(x=>x.setAttribute("aria-pressed",x===b));bg()})));bg();
  $$(".myth").forEach(b=>b.addEventListener("click",()=>{b.innerHTML=`<span class="tag l">Truth</span><b style="font-weight:500">${b.dataset.t}</b>`}));
}};

/* ======================= WHAT PASSES TO A CHILD ======================= */
const CHAN=[["DNA","--living","Conception","Physical traits, blood group, temperament tendencies, sensitivity, inherited conditions, risk variants."],["The womb","--stress","Pregnancy","Nutrition, stress hormones, alcohol, smoking, infections, medicines, the mother's health."],["Epigenetic marks","--violet","Mostly reset","Most marks are erased; a few may carry over. Strong in animals, limited evidence in humans."],["Home & relationships","--glory","Childhood onward","Attachment, emotional language, how conflict is handled, modelling, values, faith, money habits, family stories."],["The wider world","--violet","Lifelong","School, friends, culture, community, opportunities, chance events, choices."]];
const SORT=[["Eye colour","dna"],["Memories of trauma","not"],["Blood group","dna"],["Language and accent","not"],["Temperament tendencies","dna"],["Beliefs and faith","not"],["Risk for diabetes","dna"],["Skills and knowledge","not"],["How strongly you react to stress","dna"],["How to apologise and repair","not"],["Single-gene conditions like thalassaemia","dna"],["Specific fears (e.g. of dogs after a bite)","not"],["Height potential","dna"],["Manners and traditions","not"],["Taste quirks (bitterness)","dna"],["Family roles and names","not"]];
R.passes={html:()=>`
${W.head("Genetics","What passes to a child, and what doesn't","A child receives far more than DNA. Five channels shape who they become, and only one is fixed at conception.")}
<section class="panel"><div class="diagram"><svg viewBox="0 0 760 300" role="img" aria-label="Five channels flowing into the child">
 ${CHAN.map(([t,c,w],i)=>{const x=80+i*150;return`<g class="ch" data-i="${i}" style="cursor:pointer"><circle cx="${x}" cy="60" r="38" fill="var(${c})" fill-opacity=".14" stroke="var(${c})" stroke-width="2.5"/><text x="${x}" y="64" text-anchor="middle" font-size="12" font-weight="700" fill="var(--fg)">${t.split(" ")[0]}</text><text x="${x}" y="116" text-anchor="middle" font-size="12" font-weight="700" fill="var(--fg)">${t}</text><text x="${x}" y="131" text-anchor="middle" font-size="10" fill="var(--muted)">${w}</text>
  <path d="M${x} 138 C ${x} 200, 380 180, 380 235" fill="none" stroke="var(${c})" stroke-width="5" stroke-opacity=".6"/>${Array.from({length:3},(_,k)=>`<circle r="4" fill="var(${c})"><animateMotion dur="3s" begin="${k}s" repeatCount="indefinite" path="M${x} 138 C ${x} 200, 380 180, 380 235"/></circle>`).join("")}</g>`}).join("")}
 <circle cx="380" cy="262" r="34" fill="var(--living)"><animate attributeName="r" values="32;36;32" dur="3s" repeatCount="indefinite"/></circle><text x="380" y="260" text-anchor="middle" font-size="12" font-weight="700" fill="var(--bg)">The child</text><text x="380" y="274" text-anchor="middle" font-size="9" fill="var(--bg)">unique blend</text>
</svg></div><div id="chOut" class="card" style="background:var(--bg);margin-top:8px"></div></section>
${W.sec("Written in DNA vs not in DNA",null,`<div class="compare"><div class="ok"><b>Written in DNA: tendencies, not destinies</b>${W.list(["Eye, hair and skin colour; face shape; body build","Height <i>potential</i> (nutrition decides how much is reached)","Blood group and Rh factor","Biological sex chromosomes","Temperament <i>tendencies</i>: activity level, sensitivity, shyness or boldness","How strongly you react to stress and to good environments","Risk (not certainty) for diabetes, heart disease, depression, ADHD","Single-gene conditions such as thalassaemia or sickle cell disease","Taste quirks, e.g. tasting bitterness"])}</div><div class="bad"><b>Not in DNA: learned or lived</b>${W.list(["Memories, including memories of trauma","Language, accent and vocabulary","Beliefs, faith, values and opinions","Skills, knowledge and education","Habits and daily routines","Specific fears (e.g. of dogs after a bite)","Manners, culture and traditions","Names, stories and family roles","How to love, argue, apologise and repair"])}</div></div>`)}
${W.sec("Sorting game: in DNA or not?","Sort each card. Can you get all 16?",`
<div class="panel" style="display:flex;flex-direction:column;gap:14px;align-items:center;text-align:center">
 <span class="mono muted" id="sgProg"></span><div id="sgCard" class="card" style="min-height:110px;width:min(420px,100%);justify-content:center;font-family:var(--f-display);font-size:1.5rem;background:var(--bg)"></div>
 <div class="row" style="justify-content:center"><button class="btn teal" type="button" data-a="dna">In DNA</button><button class="btn" type="button" data-a="not" style="background:var(--stress);color:var(--bg);border-color:var(--stress)">Not in DNA</button></div><p id="sgFb" class="muted" style="min-height:1.5em"></p></div>`)}
${W.sec("Why some things feel inherited but travel another way","Anger patterns, anxiety, silence about feelings, people-pleasing and insecure attachment often repeat across generations. Genes may add a small push toward sensitivity, but most repeating happens through what children see, what keeps them safe, and how they are cared for.",`
<div class="grid">${[["Attachment style","Shaped mostly by caregiving; twin studies find little genetic influence on infant attachment security."],["Emotional habits","Learned by watching how parents handle stress, conflict and feelings."],["Core beliefs","'I'm too much', 'I must be perfect': absorbed from repeated experiences."],["Family rules","Unspoken rules about anger, money, success and faith, taught by example."]].map(([t,d])=>`<div class="card"><h4>${t}</h4><p>${d}</p></div>`).join("")}</div>`)}
${W.sec("Faith passes through relationship","Scripture shows faith travelling the relational channel.",`
<div class="panel"><div class="diagram"><svg viewBox="0 0 640 140" role="img" aria-label="Lois to Eunice to Timothy"><path d="M100 70 L320 70 L540 70" stroke="var(--glory)" stroke-width="3" class="flow-dash"/>${[["Lois","grandmother",100],["Eunice","mother",320],["Timothy","son",540]].map(([n,r,x])=>`<circle cx="${x}" cy="70" r="40" fill="var(--glory-soft)" stroke="var(--glory)" stroke-width="2"/><text x="${x}" y="70" text-anchor="middle" font-family="var(--f-display)" font-size="17" fill="var(--fg)">${n}</text><text x="${x}" y="86" text-anchor="middle" font-size="10" fill="var(--muted)">${r}</text>`).join("")}<circle r="6" fill="var(--glory)"><animateMotion dur="4s" repeatCount="indefinite" path="M100 70 L540 70"/></circle><text x="320" y="132" text-anchor="middle" font-size="11" fill="var(--muted)">'a sincere faith that dwelt first in your grandmother Lois and your mother Eunice and now… in you' (2 Tim 1:5)</text></svg></div>
<p style="margin-top:8px">'You shall teach them diligently to your children, and shall talk of them when you sit in your house, and when you walk by the way' (Deut 6:7). Faith, values and emotional skills pass through daily life, not genes.</p></div>`)}
${W.sec("Relational lens",null,`<div class="card" style="background:var(--violet-soft);border-color:transparent"><p style="color:var(--fg)">If a pattern travelled through relationships, it can be healed through relationships. A parent who repairs, apologises and names feelings is changing the inheritance their children receive. See <a href="#web">The living web</a> for how love outlasts iniquity.</p></div>`)}
`,mount(){
  const co=i=>{const [t,c,w,d]=CHAN[i];$$(".ch circle:first-child").forEach((x,j)=>x.setAttribute("stroke-width",j===i?5:2.5));$("#chOut").innerHTML=`<span class="tag" style="color:var(${c})">${w}</span><h4 style="margin-top:6px">${t}</h4><p style="color:var(--fg)">${d}</p>`};
  $$(".ch").forEach(g=>g.addEventListener("click",()=>co(+g.dataset.i)));co(3);
  const deck=[...SORT].sort(()=>Math.random()-.5);let i=0,score=0;
  const show=()=>{if(i>=deck.length){$("#sgCard").innerHTML=`${score} / ${deck.length} correct`;$("#sgProg").textContent="Finished";$("#sgFb").textContent=score===deck.length?"Perfect!":"Tap a button to play again.";return}$("#sgCard").textContent=deck[i][0];$("#sgProg").textContent=`Card ${i+1} of ${deck.length} · score ${score}`};
  $$("[data-a]").forEach(b=>b.addEventListener("click",()=>{if(i>=deck.length){i=0;score=0;deck.sort(()=>Math.random()-.5);$("#sgFb").textContent="";show();return}const ok=deck[i][1]===b.dataset.a;if(ok)score++;$("#sgFb").innerHTML=ok?`<b style="color:var(--living)">Correct.</b>`:`<b style="color:var(--stress)">Not quite:</b> ${esc(deck[i][0])} is ${deck[i][1]==="dna"?"written in DNA (as a tendency)":"learned or lived"}.`;i++;show()}));show();
}};

/* ======================= GENES & BEHAVIOUR ======================= */
const HER=[["Height",80,70,90,"--violet"],["Autism",80,64,91,"--violet"],["Schizophrenia",79,73,85,"--violet"],["ADHD",74,70,80,"--violet"],["Bipolar disorder",70,60,85,"--violet"],["Intelligence (adults)",60,50,80,"--glory"],["Alcohol dependence",49,43,56,"--violet"],["Personality traits",40,30,50,"--glory"],["Depression",37,31,42,"--violet"],["Happiness / wellbeing",36,30,40,"--living"],["Generalised anxiety",32,25,40,"--violet"],["Infant attachment security",10,0,25,"--stress"]];
R.behaviour={html:()=>`
${W.head("Genetics","Genes and behaviour: how much is inherited?","Genes influence behaviour indirectly, by shaping the brain's sensitivities. How much they matter depends on the trait, and environment always plays a part.")}
${W.sec("Heritability estimates from twin and family studies","Bars show a typical estimate; lines show a common range. Values vary by study, age and population. Hover or tap a bar.",`
<div class="panel"><div class="diagram"><svg id="herSvg" viewBox="0 0 720 ${HER.length*30+50}" role="img" aria-label="Heritability chart">
 ${[0,25,50,75,100].map(v=>`<line x1="${200+v*4.8}" y1="10" x2="${200+v*4.8}" y2="${HER.length*30+16}" stroke="var(--line)"/><text x="${200+v*4.8}" y="${HER.length*30+34}" text-anchor="middle" font-size="10" font-family="var(--f-mono)" fill="var(--muted)">${v}%</text>`).join("")}
 ${HER.map(([t,v,lo,hi,c],i)=>{const y=14+i*30;return`<g class="her" data-i="${i}"><text x="190" y="${y+12}" text-anchor="end" font-size="11.5" font-weight="700" fill="var(--fg)">${t}</text><rect x="200" y="${y}" width="0" height="16" rx="8" fill="var(${c})" opacity=".45"><animate attributeName="width" values="0;${v*4.8}" dur="1s" begin="${i*.06}s" fill="freeze"/></rect><line x1="${200+lo*4.8}" y1="${y+8}" x2="${200+hi*4.8}" y2="${y+8}" stroke="var(--fg)" stroke-width="1.5"/><line x1="${200+lo*4.8}" y1="${y+2}" x2="${200+lo*4.8}" y2="${y+14}" stroke="var(--fg)" stroke-width="1.5"/><line x1="${200+hi*4.8}" y1="${y+2}" x2="${200+hi*4.8}" y2="${y+14}" stroke="var(--fg)" stroke-width="1.5"/><circle cx="${200+v*4.8}" cy="${y+8}" r="5" fill="var(${c})"/><text x="${206+hi*4.8}" y="${y+12}" font-size="10" font-family="var(--f-mono)" fill="var(--muted)">${i===HER.length-1?"low: shaped mostly by caregiving":"~"+v+"%"}</text></g>`}).join("")}
</svg></div><p class="muted" style="font-size:.82rem;margin-top:6px">Heritability of intelligence rises with age, from about 20% in infancy to around 60% in adulthood. Approximate figures from twin and family studies (e.g. Polderman et al., 2015).</p></div>`)}
${W.sec("What 'heritability' really means",null,`<div class="grid">${[["It is about differences","The share of variation between people in a group linked to genetic differences."],["It is not about you","'40% heritable' does not mean 40% of your personality comes from genes."],["It is not destiny","A highly heritable trait can still change a lot with environment."],["Example: height","~80% heritable, yet South Korean women gained about 20 cm on average during the 20th century as nutrition improved."]].map(([t,d])=>`<div class="card"><h4>${t}</h4><p>${d}</p></div>`).join("")}</div>`)}
${W.sec("How a gene can influence behaviour","Environment acts at every step.",`
<div class="panel"><div class="diagram"><svg viewBox="0 0 760 190" role="img" aria-label="Gene to behaviour pathway">
 ${[["Thousands of gene variants","each a tiny effect"],["Proteins & brain chemistry","serotonin, dopamine, stress hormones"],["Brain development","wiring, sensitivity, reactivity"],["Temperament","calm or reactive, shy or bold"],["Behaviour & personality","how you actually live and relate"]].map(([t,s],i)=>`<rect x="${10+i*150}" y="20" width="135" height="64" rx="12" fill="var(--violet-soft)" stroke="var(--violet)" stroke-width="1.6"/><foreignObject x="${14+i*150}" y="24" width="127" height="58"><div xmlns="http://www.w3.org/1999/xhtml" style="font-size:11.5px;font-weight:700;text-align:center;color:var(--fg);line-height:1.2">${t}<div style="font-weight:400;font-size:9.5px;color:var(--muted);margin-top:3px">${s}</div></div></foreignObject>${i<4?`<path d="M${145+i*150} 52 L${160+i*150} 52" stroke="var(--violet)" stroke-width="3"/>`:""}<path d="M${77+i*150} 84 L${77+i*150} 130" stroke="var(--glory)" stroke-width="2" stroke-dasharray="3 4"/><circle r="4" fill="var(--glory)"><animateMotion dur="2s" begin="${i*.3}s" repeatCount="indefinite" path="M${77+i*150} 132 L${77+i*150} 86"/></circle>`).join("")}
 <rect x="10" y="132" width="735" height="40" rx="12" fill="var(--glory-soft)" stroke="var(--glory)"/><text x="377" y="157" text-anchor="middle" font-size="12" font-weight="700" fill="var(--fg)">Environment acts at every step: nutrition, stress, care, relationships, culture, faith, choices</text>
</svg></div><p style="margin-top:10px">There is <b>no single gene</b> for anger, kindness, faith, addiction or intelligence. Genes build a brain with certain sensitivities; experience decides how those sensitivities are used.</p></div>`)}
${W.sec("Genes and environment shape each other",null,`<div class="grid">${[["Passive","Parents give both genes and a home. A musical parent passes on genes and also fills the house with music."],["Evocative","A child's temperament draws out reactions: a smiley baby gets more smiles back."],["Active","As we grow we choose settings that fit us: a curious child seeks books and friends who reinforce it."]].map(([t,d])=>`<div class="card"><span class="tag g">G × E</span><h4>${t}</h4><p>${d}</p></div>`).join("")}</div>`)}
${W.sec("Sensitive children: orchids and dandelions","Drag the environment from harsh to supportive (differential susceptibility, Belsky & Pluess, 2009).",`
<div class="split"><div class="panel"><div class="diagram"><svg id="odSvg" viewBox="0 0 420 260" style="min-width:0" role="img" aria-label="Orchid and dandelion lines">
 <line x1="50" y1="220" x2="400" y2="220" stroke="var(--fg)"/><line x1="50" y1="20" x2="50" y2="220" stroke="var(--fg)"/><text x="225" y="250" text-anchor="middle" font-size="10.5" font-family="var(--f-mono)" fill="var(--muted)">Environment: harsh → supportive</text><text x="20" y="120" transform="rotate(-90 20 120)" text-anchor="middle" font-size="10.5" font-family="var(--f-mono)" fill="var(--muted)">Wellbeing →</text>
 <line x1="60" y1="205" x2="390" y2="30" stroke="var(--violet)" stroke-width="3"/><line x1="60" y1="140" x2="390" y2="95" stroke="var(--glory)" stroke-width="3"/>
 <circle id="odO" r="9" fill="var(--violet)"/><circle id="odD" r="9" fill="var(--glory)"/><line id="odL" y1="20" y2="220" stroke="var(--muted)" stroke-dasharray="4 4"/>
 <text x="70" y="40" font-size="11" fill="var(--violet)">● more sensitive ("orchid")</text><text x="70" y="58" font-size="11" fill="var(--glory)">● less sensitive ("dandelion")</text>
</svg></div><input id="odSl" type="range" min="0" max="100" value="20" style="margin-top:8px"></div>
<div class="panel" id="odOut" style="display:flex;flex-direction:column;gap:10px"></div></div>`)}
${W.sec("Relational lens",null,`<div class="grid two"><div class="card" style="background:var(--violet-soft);border-color:transparent"><p style="color:var(--fg)">A sensitive temperament is not a flaw to fix but a nervous system to understand. The same sensitivity that makes a child vulnerable to harshness makes them especially responsive to love.</p></div>
<div class="card"><span class="tag g">Scripture</span><p>'Train up a child in the way he should go' (Prov 22:6) can be read as 'according to his way': fitted to the child's own bent. 'There are varieties of gifts, but the same Spirit' (1 Cor 12:4). God designs difference on purpose.</p></div></div>`)}
`,mount(){
  $$("#herSvg .her").forEach(g=>g.addEventListener("click",()=>{const h=HER[+g.dataset.i];toast(`${h[0]}: about ${h[1]}% (range ${h[2]}–${h[3]}%)`)}));
  const od=()=>{const s=+$("#odSl").value/100;const x=60+s*330;const yo=205-s*175,yd=140-s*45;$("#odO").setAttribute("cx",x);$("#odO").setAttribute("cy",yo);$("#odD").setAttribute("cx",x);$("#odD").setAttribute("cy",yd);$("#odL").setAttribute("x1",x);$("#odL").setAttribute("x2",x);
   $("#odOut").innerHTML=`<span class="tag ${s<.4?"s":s>.6?"l":"g"}">${s<.4?"Harsh setting":s>.6?"Supportive setting":"Mixed setting"}</span><h3>${s<.4?"Orchids struggle more":s>.6?"Orchids flourish most":"Close to the crossover"}</h3><p>${s<.4?"Sensitive children react more strongly to harsh, chaotic or cold care. Dandelions cope more steadily.":s>.6?"With warm, attuned care, sensitive children often outperform their peers: more empathy, creativity and wellbeing.":"Here both temperaments do about the same. Small changes in care make a big difference to the orchid."}</p>`};
  $("#odSl").oninput=od;od();
}};
})();
